    sw2hw_o.ctrl_rx.rx_parity_odd    <= ctrl_rx_rdata_hw(2 downto 2);
    sw2hw_o.ctrl_rx.rx_use_loopback  <= ctrl_rx_rdata_hw(3 downto 3);
    sw2hw_o.ctrl_rx.rts_enable       <= ctrl_rx_rdata_hw(4 downto 4);
    ins_ctrl_rx : csr_reg
      generic map
        (WIDTH => 5
        ,INIT  => INIT_ctrl_rx
        ,MODEL => "rw"
        )
      port map
        (clk_i      => clk_i
        ,arst_b_i   => arst_b_i
        ,sw_wd_i    => ctrl_rx_wdata_sw
        ,sw_rd_o    => ctrl_rx_rdata_sw
        ,sw_we_i    => ctrl_rx_we
        ,sw_re_i    => ctrl_rx_re
        ,sw_rbusy_o => ctrl_rx_rbusy
        ,sw_wbusy_o => ctrl_rx_wbusy
        ,hw_wd_i    => (others => '0')
        ,hw_rd_o    => ctrl_rx_rdata_hw
        ,hw_we_i    => '0'
        ,hw_sw_re_o => sw2hw_o.ctrl_rx.re
        ,hw_sw_we_o => sw2hw_o.ctrl_rx.we
        );
  end generate gen_ctrl_rx;

  gen_ctrl_rx_b: if not (true) generate
    ctrl_rx_rcs                      <= '0';
    ctrl_rx_rbusy                    <= '0';
    ctrl_rx_rdata                    <= (others => '0');
    ctrl_rx_wcs                      <= '0';
    ctrl_rx_wbusy                    <= '0';
    sw2hw_o.ctrl_rx.re               <= '0';
    sw2hw_o.ctrl_rx.we               <= '0';
    sw2hw_o.ctrl_rx.rx_enable        <= INIT_ctrl_rx_rx_enable;
    sw2hw_o.ctrl_rx.rx_parity_enable <= INIT_ctrl_rx_rx_parity_enable;
    sw2hw_o.ctrl_rx.rx_parity_odd    <= INIT_ctrl_rx_rx_parity_odd;
    sw2hw_o.ctrl_rx.rx_use_loopback  <= INIT_ctrl_rx_rx_use_loopback;
    sw2hw_o.ctrl_rx.rts_enable       <= INIT_ctrl_rx_rts_enable;
  end generate gen_ctrl_rx_b;

  --==================================
  -- Register    : baud_tick_cnt_max_lsb
  -- Description : Baud Tick Counter Max LSB. Must be equal to (Clock Frequency (Hz) / Baud Rate)-1. Write it at setup time, with ctrl_tx.tx_enable = ctrl_rx.rx_enable = 0 (baud rate generators held in reset)
  -- Address     : 0x6
  -- Width       : 8
  -- Sw Access   : rw
  -- Hw Access   : ro
  -- Hw Type     : reg
  --==================================
  gen_baud_tick_cnt_max_lsb: if (USER_DEFINE_BAUD_TICK) generate
    constant INIT_baud_tick_cnt_max_lsb     : std_logic_vector(7 downto 0) := INIT_baud_tick_cnt_max_lsb_value;
    signal   baud_tick_cnt_max_lsb_re       : std_logic;
    signal   baud_tick_cnt_max_lsb_we       : std_logic;
    signal   baud_tick_cnt_max_lsb_wdata_sw : std_logic_vector(7 downto 0);
    signal   baud_tick_cnt_max_lsb_rdata_sw : std_logic_vector(7 downto 0);
    signal   baud_tick_cnt_max_lsb_rdata_hw : std_logic_vector(7 downto 0);
  begin
    baud_tick_cnt_max_lsb_rcs <= '1' when sig_raddr = UART_BAUD_TICK_CNT_MAX_LSB else
                                 '0';
    baud_tick_cnt_max_lsb_re    <= sig_rcs and sig_re and baud_tick_cnt_max_lsb_rcs;
    baud_tick_cnt_max_lsb_rdata <= baud_tick_cnt_max_lsb_rdata_sw(7 downto 0);
    baud_tick_cnt_max_lsb_wcs <= '1' when sig_waddr = UART_BAUD_TICK_CNT_MAX_LSB else
                                 '0';
    baud_tick_cnt_max_lsb_we            <= sig_wcs and sig_we and baud_tick_cnt_max_lsb_wcs;
    baud_tick_cnt_max_lsb_wdata_sw      <= sig_wdata(7 downto 0);
    sw2hw_o.baud_tick_cnt_max_lsb.value <= baud_tick_cnt_max_lsb_rdata_hw(7 downto 0);
    ins_baud_tick_cnt_max_lsb : csr_reg
      generic map
        (WIDTH => 8
        ,INIT  => INIT_baud_tick_cnt_max_lsb
        ,MODEL => "rw"
        )
      port map
        (clk_i      => clk_i
        ,arst_b_i   => arst_b_i
        ,sw_wd_i    => baud_tick_cnt_max_lsb_wdata_sw
        ,sw_rd_o    => baud_tick_cnt_max_lsb_rdata_sw
        ,sw_we_i    => baud_tick_cnt_max_lsb_we
        ,sw_re_i    => baud_tick_cnt_max_lsb_re
        ,sw_rbusy_o => baud_tick_cnt_max_lsb_rbusy
        ,sw_wbusy_o => baud_tick_cnt_max_lsb_wbusy
        ,hw_wd_i    => (others => '0')
        ,hw_rd_o    => baud_tick_cnt_max_lsb_rdata_hw
        ,hw_we_i    => '0'
        ,hw_sw_re_o => sw2hw_o.baud_tick_cnt_max_lsb.re
        ,hw_sw_we_o => sw2hw_o.baud_tick_cnt_max_lsb.we
        );
  end generate gen_baud_tick_cnt_max_lsb;

  gen_baud_tick_cnt_max_lsb_b: if not (USER_DEFINE_BAUD_TICK) generate
    baud_tick_cnt_max_lsb_rcs           <= '0';
    baud_tick_cnt_max_lsb_rbusy         <= '0';
    baud_tick_cnt_max_lsb_rdata         <= (others => '0');
    baud_tick_cnt_max_lsb_wcs           <= '0';
    baud_tick_cnt_max_lsb_wbusy         <= '0';
    sw2hw_o.baud_tick_cnt_max_lsb.re    <= '0';
    sw2hw_o.baud_tick_cnt_max_lsb.we    <= '0';
    sw2hw_o.baud_tick_cnt_max_lsb.value <= INIT_baud_tick_cnt_max_lsb_value;
  end generate gen_baud_tick_cnt_max_lsb_b;

  --==================================
  -- Register    : baud_tick_cnt_max_msb
  -- Description : Baud Tick Counter Max MSB. Must be equal to (Clock Frequency (Hz) / Baud Rate)-1. Write it at setup time, with ctrl_tx.tx_enable = ctrl_rx.rx_enable = 0 (baud rate generators held in reset)
  -- Address     : 0x7
  -- Width       : 8
  -- Sw Access   : rw
  -- Hw Access   : ro
  -- Hw Type     : reg
  --==================================
  gen_baud_tick_cnt_max_msb: if (USER_DEFINE_BAUD_TICK) generate
    constant INIT_baud_tick_cnt_max_msb     : std_logic_vector(7 downto 0) := INIT_baud_tick_cnt_max_msb_value;
    signal   baud_tick_cnt_max_msb_re       : std_logic;
    signal   baud_tick_cnt_max_msb_we       : std_logic;
    signal   baud_tick_cnt_max_msb_wdata_sw : std_logic_vector(7 downto 0);
    signal   baud_tick_cnt_max_msb_rdata_sw : std_logic_vector(7 downto 0);
    signal   baud_tick_cnt_max_msb_rdata_hw : std_logic_vector(7 downto 0);
  begin
    baud_tick_cnt_max_msb_rcs <= '1' when sig_raddr = UART_BAUD_TICK_CNT_MAX_MSB else
                                 '0';
    baud_tick_cnt_max_msb_re    <= sig_rcs and sig_re and baud_tick_cnt_max_msb_rcs;
    baud_tick_cnt_max_msb_rdata <= baud_tick_cnt_max_msb_rdata_sw(7 downto 0);
    baud_tick_cnt_max_msb_wcs <= '1' when sig_waddr = UART_BAUD_TICK_CNT_MAX_MSB else
                                 '0';
    baud_tick_cnt_max_msb_we            <= sig_wcs and sig_we and baud_tick_cnt_max_msb_wcs;
    baud_tick_cnt_max_msb_wdata_sw      <= sig_wdata(7 downto 0);
    sw2hw_o.baud_tick_cnt_max_msb.value <= baud_tick_cnt_max_msb_rdata_hw(7 downto 0);
    ins_baud_tick_cnt_max_msb : csr_reg
      generic map
        (WIDTH => 8
        ,INIT  => INIT_baud_tick_cnt_max_msb
        ,MODEL => "rw"
        )
      port map
        (clk_i      => clk_i
        ,arst_b_i   => arst_b_i
        ,sw_wd_i    => baud_tick_cnt_max_msb_wdata_sw
        ,sw_rd_o    => baud_tick_cnt_max_msb_rdata_sw
        ,sw_we_i    => baud_tick_cnt_max_msb_we
        ,sw_re_i    => baud_tick_cnt_max_msb_re
        ,sw_rbusy_o => baud_tick_cnt_max_msb_rbusy
        ,sw_wbusy_o => baud_tick_cnt_max_msb_wbusy
        ,hw_wd_i    => (others => '0')
        ,hw_rd_o    => baud_tick_cnt_max_msb_rdata_hw
        ,hw_we_i    => '0'
        ,hw_sw_re_o => sw2hw_o.baud_tick_cnt_max_msb.re
        ,hw_sw_we_o => sw2hw_o.baud_tick_cnt_max_msb.we
        );
  end generate gen_baud_tick_cnt_max_msb;

  gen_baud_tick_cnt_max_msb_b: if not (USER_DEFINE_BAUD_TICK) generate
    baud_tick_cnt_max_msb_rcs           <= '0';
    baud_tick_cnt_max_msb_rbusy         <= '0';
    baud_tick_cnt_max_msb_rdata         <= (others => '0');
    baud_tick_cnt_max_msb_wcs           <= '0';
    baud_tick_cnt_max_msb_wbusy         <= '0';
    sw2hw_o.baud_tick_cnt_max_msb.re    <= '0';
    sw2hw_o.baud_tick_cnt_max_msb.we    <= '0';
    sw2hw_o.baud_tick_cnt_max_msb.value <= INIT_baud_tick_cnt_max_msb_value;
  end generate gen_baud_tick_cnt_max_msb_b;

  -- Busy and read data (unmapped address : no busy, read 0)
  sig_wbusy <= isr_wbusy when isr_wcs = '1' else
               imr_wbusy when imr_wcs = '1' else
               data_wbusy when data_wcs = '1' else
               ctrl_tx_wbusy when ctrl_tx_wcs = '1' else
               ctrl_rx_wbusy when ctrl_rx_wcs = '1' else
               baud_tick_cnt_max_lsb_wbusy when baud_tick_cnt_max_lsb_wcs = '1' else
               baud_tick_cnt_max_msb_wbusy when baud_tick_cnt_max_msb_wcs = '1' else
               '0';
  sig_rbusy <= isr_rbusy when isr_rcs = '1' else
               imr_rbusy when imr_rcs = '1' else
               data_rbusy when data_rcs = '1' else
               ctrl_tx_rbusy when ctrl_tx_rcs = '1' else
               ctrl_rx_rbusy when ctrl_rx_rcs = '1' else
               baud_tick_cnt_max_lsb_rbusy when baud_tick_cnt_max_lsb_rcs = '1' else
               baud_tick_cnt_max_msb_rbusy when baud_tick_cnt_max_msb_rcs = '1' else
               '0';
  sig_rdata <= isr_rdata when isr_rcs = '1' else
               imr_rdata when imr_rcs = '1' else
               data_rdata when data_rcs = '1' else
               ctrl_tx_rdata when ctrl_tx_rcs = '1' else
               ctrl_rx_rdata when ctrl_rx_rcs = '1' else
               baud_tick_cnt_max_lsb_rdata when baud_tick_cnt_max_lsb_rcs = '1' else
               baud_tick_cnt_max_msb_rdata when baud_tick_cnt_max_msb_rcs = '1' else
               (others => '0');

end architecture rtl;
